mapper.select:
SELECT diary_date
FROM diary
WHERE user_id = #{userId}
  AND YEAR(diary_date)  = #{year}
  AND MONTH(diary_date) = #{month}
ORDER BY diary_date

SELECT did, user_id, diary_date, content, ai_feedback, created_at
FROM diary
WHERE user_id = #{userId}
  AND diary_date = #{diaryDate}

SELECT COUNT(*)
FROM diary
WHERE user_id = #{userId}
  AND diary_date = #{diaryDate}

mapper.update:
UPDATE diary
SET content = #{content}
WHERE did = #{did}
  AND user_id = #{userId}

mapper.delete:
DELETE FROM diary
WHERE did = #{did}
  AND user_id = #{userId}

